import java.util.*;

public class Main {
    static final long MOD = 1000000007;

    static class DisjointSet {
        long[] parent;

        public DisjointSet(long n) {
            parent = new long[(int) n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public long find(long a) {
            if (parent[(int) a] == a) {
                return a;
            }
            parent[(int) a] = find(parent[(int) a]);
            return parent[(int) a];
        }

        public void union_sets(long a, long b) {
            a = find(a);
            b = find(b);
            if (a != b) {
                Random rand = new Random();
                if (rand.nextInt(2) == 0) {
                    long temp = a;
                    a = b;
                    b = temp;
                }
                parent[(int) b] = a;
            }
        }
    }

    static long count_cycles(long total, long mult) {
        DisjointSet ds = new DisjointSet(total);
        for (long i = 1; i < total; ++i) {
            long target = (mult * i) % total;
            ds.union_sets(i, target);
        }
        boolean[] visited = new boolean[(int) total];
        long cycle_count = 0;
        for (long i = 1; i < total; ++i) {
            long root = ds.find(i);
            if (!visited[(int) root]) {
                visited[(int) root] = true;
                ++cycle_count;
            }
        }
        return cycle_count;
    }

    static long solve(long total, long mult) {
        long cycles;
        if (mult == 0) {
            cycles = total - 1;
        } else if (mult == 1) {
            cycles = total;
        } else {
            cycles = count_cycles(total, mult);
        }
        long result = 1;
        for (long i = 0; i < cycles; ++i) {
            result = (result * total) % MOD;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();
        System.out.println(solve(p, k));
        int dummy = sc.nextInt(); // read dummy input
        sc.close();
    }
}
